<?php
$cv=$cv??[];$educations=$educations??[];$workHistories=$workHistories??[];$certificatesOfCv=$certificatesOfCv??[];$skillsOfCv=$skillsOfCv??[];
$h=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');
$pick=function($r,$keys,$d=''){foreach((array)$keys as $k){if(isset($r[$k])&&$r[$k]!=='')return $r[$k];}return $d;};
$name=$pick($cv,['full_name','name'],'Untitled CV');$id=$pick($cv,['id','cv_id'],'');$category=$pick($cv,['category_name','category'],'Online CV');$email=$pick($cv,'email');$phone=$pick($cv,['phone_number','phone']);
$location=implode(' · ',array_filter([$pick($cv,['city_name','city']),$pick($cv,['country_name','country'])]));$period=fn($r)=>trim(($pick($r,'start_year')?:'').' — '.($pick($r,'end_year')?:'Present'));
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Minimal CV</title><style>
:root{--ink:#111827;--muted:#6b7280;--line:#e5e7eb;--soft:#f9fafb}*{box-sizing:border-box}body{margin:0;background:#f3f4f6;color:var(--ink);font-family:Inter,Segoe UI,Arial,sans-serif}.sheet{width:min(900px,calc(100% - 30px));margin:30px auto;background:#fff;padding:58px 66px;box-shadow:0 22px 60px rgba(17,24,39,.10)}.hero{display:grid;grid-template-columns:1fr auto;gap:28px;align-items:end;border-bottom:1px solid var(--line);padding-bottom:30px}.eyebrow{font-size:12px;letter-spacing:2.4px;text-transform:uppercase;color:var(--muted);font-weight:900;margin-bottom:14px}h1{font-size:clamp(42px,7vw,72px);line-height:.92;letter-spacing:-3px;margin:0}.contact{text-align:right;display:grid;gap:7px;color:var(--muted);font-size:14px}.actions{display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap;margin:18px 0}.actions a{text-decoration:none;padding:10px 15px;border-radius:999px;font-size:13px;font-weight:800}.actions .secondary{background:#f3f4f6;color:#111827}.actions .edit{background:#111827;color:#fff}.summary{font-size:19px;line-height:1.75;margin:28px 0 38px}.grid{display:grid;grid-template-columns:180px 1fr;gap:28px 44px}.label{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:var(--muted);font-weight:900}.body{border-bottom:1px solid var(--line);padding-bottom:26px}.item{margin-bottom:22px}.item:last-child{margin-bottom:0}.item-head{display:flex;justify-content:space-between;gap:16px}.item-title{font-size:18px;font-weight:900}.time{color:var(--muted);font-size:13px;white-space:nowrap}.sub{color:var(--muted);margin:5px 0 9px}.desc{line-height:1.65;color:#374151}.chips{display:flex;gap:10px;flex-wrap:wrap}.chip{background:var(--soft);border:1px solid var(--line);border-radius:999px;padding:9px 13px;font-size:13px}.empty{color:var(--muted);font-style:italic}@media(max-width:760px){.sheet{padding:36px 24px}.hero,.grid{grid-template-columns:1fr}.contact{text-align:left}.item-head{display:block}h1{letter-spacing:-1.5px}}
</style></head><body><div class="sheet"><header class="hero"><div><div class="eyebrow"><?= $h($category) ?></div><h1><?= $h($name) ?></h1></div><div class="contact"><?php if($email):?><div><?= $h($email) ?></div><?php endif;?><?php if($phone):?><div><?= $h($phone) ?></div><?php endif;?><?php if($location):?><div><?= $h($location) ?></div><?php endif;?></div></header><div class="actions"><a class="secondary" href="?route=seeker/cv/templates<?= $id?'&id='.$h($id):'' ?>">Change Template</a><a class="edit" href="?route=seeker/cv/edit">Edit CV</a></div><?php if(!empty($cv['summary'])):?><section class="summary"><?= nl2br($h($cv['summary'])) ?></section><?php endif;?><main class="grid"><div class="label">Education</div><section class="body"><?php if($educations): foreach($educations as $e):?><div class="item"><div class="item-head"><div class="item-title"><?= $h($pick($e,['degree_name','degree'],'Education')) ?></div><div class="time"><?= $h($period($e)) ?></div></div><div class="sub"><?= $h(implode(' · ',array_filter([$pick($e,['institution_name','institution']),$pick($e,['major_name','major'])]))) ?></div><?php if($pick($e,'description')):?><div class="desc"><?= nl2br($h($pick($e,'description'))) ?></div><?php endif;?></div><?php endforeach; else:?><p class="empty">No education records.</p><?php endif;?></section><div class="label">Experience</div><section class="body"><?php if($workHistories): foreach($workHistories as $w):?><div class="item"><div class="item-head"><div class="item-title"><?= $h($pick($w,['job_title_name','job_title'],'Work Experience')) ?></div><div class="time"><?= $h($period($w)) ?></div></div><div class="sub"><?= $h(implode(' · ',array_filter([$pick($w,'company_name'),$pick($w,['employment_type_name','employment_type']),$pick($w,['industry_name','industry'])]))) ?></div><?php if($pick($w,['job_description','description'])):?><div class="desc"><?= nl2br($h($pick($w,['job_description','description']))) ?></div><?php endif;?></div><?php endforeach; else:?><p class="empty">No work history records.</p><?php endif;?></section><div class="label">Skills</div><section class="body"><div class="chips"><?php if($skillsOfCv): foreach($skillsOfCv as $s):?><span class="chip"><?= $h($pick($s,['skill_name','skill'],'Skill')) ?><?php if($pick($s,['proficiency_name','proficiency'])):?> <span>· <?= $h($pick($s,['proficiency_name','proficiency'])) ?></span><?php endif;?></span><?php endforeach; else:?><span class="empty">No skills.</span><?php endif;?></div></section><div class="label">Certificates</div><section class="body"><?php if($certificatesOfCv): foreach($certificatesOfCv as $c):?><div class="item"><div class="item-head"><div class="item-title"><?= $h($pick($c,['certificate_name','certificate'],'Certificate')) ?></div><div class="time"><?= $h($pick($c,'year_issued')) ?></div></div><div class="sub"><?= $h($pick($c,['organization_name','organization'])) ?></div></div><?php endforeach; else:?><p class="empty">No certificates.</p><?php endif;?></section></main></div></body></html>
